class Solution {
  public int smallestAbsent(int[] nums) {
    int sum = 0;
    Set<Integer> present = new HashSet<>();
    for (int x : nums) {
      sum += x;
      present.add(x);
    }
    int x = Math.max(1, Math.floorDiv(sum, nums.length) + 1);
    while (present.contains(x)) x++;
    return x;
  }
}
